-- =============================================================================
-- PROCEDURE 4: Table-valued parameter procedure
-- Bulk-inserts employees from a TVP with validation
-- =============================================================================

CREATE OR REPLACE PROCEDURE public.sp_BulkInsertEmployees(
    p_Employees public.EmployeeBatchType[],
    INOUT p_InsertedCount INT DEFAULT 0
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_row_count INT;
BEGIN
    p_InsertedCount := 0;

    -- Validate all departments exist
    IF EXISTS (
        SELECT 1 FROM UNNEST(p_Employees) e
        WHERE NOT EXISTS (
            SELECT 1 FROM public.Departments d 
            WHERE d.DepartmentID = e.DepartmentID
        )
    ) THEN
        RAISE EXCEPTION 'One or more department IDs are invalid' 
            USING ERRCODE = '50010';
    END IF;

    -- Validate no duplicate emails against existing data
    IF EXISTS (
        SELECT 1 FROM UNNEST(p_Employees) e
        INNER JOIN public.Employees existing ON existing.Email = e.Email
    ) THEN
        RAISE EXCEPTION 'One or more email addresses already exist' 
            USING ERRCODE = '50011';
    END IF;

    -- Insert from array parameter
    INSERT INTO public.Employees (FirstName, LastName, Email, DepartmentID, Salary)
    SELECT e.FirstName, e.LastName, e.Email, e.DepartmentID, e.Salary
    FROM UNNEST(p_Employees) e;

    GET DIAGNOSTICS v_row_count = ROW_COUNT;
    p_InsertedCount := v_row_count;

    -- Log the bulk operation
    INSERT INTO public.AuditLog (TableName, Operation, RecordID, NewValues)
    VALUES ('Employees', 'BULK_INSERT', p_InsertedCount, 'Batch insert via TVP');

    -- Return result set (requires wrapper function for exact compatibility)
    RAISE NOTICE 'TotalInserted: %', p_InsertedCount;
END;
$$;

-- =============================================================================
-- PROCEDURE 1: Cursor-based processing
-- Iterates through employees and applies salary adjustments per department rules
-- =============================================================================

CREATE OR REPLACE FUNCTION public.sp_CursorSalaryAdjustment(
    p_AdjustmentPercent DECIMAL(5,2),
    p_DepartmentID INT DEFAULT NULL
)
RETURNS TABLE(
    EmployeesProcessed INT,
    AdjustmentPercent DECIMAL(5,2)
)
LANGUAGE plpgsql
AS $$
DECLARE
    v_EmpID INT;
    v_CurrentSalary DECIMAL(10,2);
    v_NewSalary DECIMAL(10,2);
    v_EmpDeptID INT;
    v_ProcessedCount INT := 0;
    v_DeptBudget DECIMAL(12,2);
    v_DeptCount INT;
    emp_cursor CURSOR FOR
        SELECT EmployeeID, Salary, DepartmentID
        FROM public.Employees
        WHERE (p_DepartmentID IS NULL OR DepartmentID = p_DepartmentID)
          AND Salary > 0;
BEGIN
    -- Open cursor and iterate through employees
    OPEN emp_cursor;

    LOOP
        FETCH NEXT FROM emp_cursor INTO v_EmpID, v_CurrentSalary, v_EmpDeptID;
        EXIT WHEN NOT FOUND;

        -- Calculate new salary
        v_NewSalary := v_CurrentSalary * (1 + p_AdjustmentPercent / 100.0);

        -- Cap salary at department budget / employee count
        SELECT BudgetAmount INTO v_DeptBudget 
        FROM public.Departments 
        WHERE DepartmentID = v_EmpDeptID;

        SELECT COUNT(*) INTO v_DeptCount 
        FROM public.Employees 
        WHERE DepartmentID = v_EmpDeptID;

        IF v_DeptCount > 0 AND v_NewSalary > (v_DeptBudget / v_DeptCount) THEN
            v_NewSalary := v_DeptBudget / v_DeptCount;
        END IF;

        -- Record history
        INSERT INTO public.SalaryHistory (EmployeeID, OldSalary, NewSalary, Reason)
        VALUES (v_EmpID, v_CurrentSalary, v_NewSalary, 
                'Annual adjustment ' || p_AdjustmentPercent::TEXT || '%');

        -- Apply update
        UPDATE public.Employees 
        SET Salary = v_NewSalary 
        WHERE EmployeeID = v_EmpID;

        v_ProcessedCount := v_ProcessedCount + 1;
    END LOOP;

    CLOSE emp_cursor;

    -- Return result set
    RETURN QUERY SELECT v_ProcessedCount, p_AdjustmentPercent;
END;
$$;
